name.arcade:
// The layer spells two names differently from the National Park Service's own usage.
var n = Proper(Lower($feature.NAME));
n = Replace(n, 'Glorietta', 'Glorieta');
n = Replace(n, 'St.phillip', 'St. Philip');
return n;

what.arcade:
var st = Decode(Trim($feature.STATE), 'AL', 'Alabama', 'AR', 'Arkansas', 'CO', 'Colorado', 'DC', 'Washington, D.C.', 'FL', 'Florida', 'GA', 'Georgia', 'ID', 'Idaho', 'IN', 'Indiana', 'KS', 'Kansas', 'KY', 'Kentucky', 'LA', 'Louisiana', 'MD', 'Maryland', 'MN', 'Minnesota', 'MO', 'Missouri', 'MS', 'Mississippi', 'NC', 'North Carolina', 'ND', 'North Dakota', 'NM', 'New Mexico', 'OH', 'Ohio', 'OK', 'Oklahoma', 'PA', 'Pennsylvania', 'SC', 'South Carolina', 'TN', 'Tennessee', 'TX', 'Texas', 'VA', 'Virginia', 'WV', 'West Virginia', '');
var inSt = IIf(st == '', '', ' in ' + st);
var n = Upper(Trim($feature.NAME));
if (n == 'SAND CREEK') { return 'The site of the Sand Creek Massacre,' + inSt + '. In November 1864 United States volunteer troops attacked a Cheyenne and Arapaho village here.'; }
if (n == 'BEAR RIVER') { return 'The site of the Bear River Massacre,' + inSt + '. In January 1863 United States volunteer troops attacked a Northwestern Shoshone village here.'; }
return 'A Civil War battlefield' + inSt + '.';

note.arcade:
var n = Upper(Trim($feature.NAME));
if (n == 'SAND CREEK' || n == 'BEAR RIVER') { return 'The National Park Service maps this area with its Civil War battlefields. It was an attack on a village, not a battle.'; }
return 'The area is the land where the battle was fought, as mapped by the National Park Service. This layer does not say who won.';
